function badge(s){return `<span class="badge ${s==='直播中'?'live':['可用','已完成','已核销','已退款','已发送','已审核'].includes(s)?'ok':['待发货','待审核','待支付','待核销','待处理','待开播'].includes(s)?'wait':s==='已结束'?'gray':''}">${E(s)}</span>`}function title(t,sub='',buttons=''){return `<div class="title-row"><div><h1>${t}</h1><p>${sub}</p></div><div class="actions">${buttons}</div></div>`}function scrollTop(){if(typeof window!=='undefined')window.scrollTo(0,0)}function go(p){page=p;searchTerm='';if(p==='comments')window.assistantSubTab='all';else if(p==='scripts')window.assistantSubTab='scripts';else if(p==='robots')window.assistantSubTab='robots';render();scrollTop()}function switchSurface(s){surface=s;try{const u=new URL(location.href);if(s==='pc'){u.searchParams.delete('view');u.searchParams.delete('room');}else{u.searchParams.set('view',s);if(!u.searchParams.has('room'))u.searchParams.set('room',String(roomId));}history.replaceState(null,'',u.href);}catch(e){}render();scrollTop()}function navigateMini(p,tab){miniPage=p;if(tab)miniTab=tab;render();scrollTop()}function modal(t,body,footer=''){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${t}</h2><button onclick="closeDialog()" aria-label="关闭">×</button></div>${body}${footer?`<div class="dialog-foot">${footer}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal()}function closeDialog(){$('#dialog').close();$('#dialog').innerHTML=''}function footSave(fn='submitConfig(event)'){return `<div class="dialog-foot"><button type="button" onclick="closeDialog()">取消</button><button class="primary" type="submit">保存设置</button></div>`}function product(id){return db.products.find(p=>p.id===Number(id))||db.products[0]}function room(){return db.rooms.find(r=>r.id===roomId)||db.rooms[0]}function productPic(p,cls=''){return `<img class="${cls}" src="assets/beauty-products.png" alt="${E(p.name)} · AI示意产品图">`}function filterTable(v){let n=0;$$('tbody tr').forEach(r=>{r.hidden=!r.textContent.toLowerCase().includes(v.toLowerCase());n+=!r.hidden});if($('#empty-search'))$('#empty-search').hidden=n>0}function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>${rows.length?'':'<div class="empty">暂无记录</div>'}<p id="empty-search" class="empty" hidden>未找到匹配记录</p><div class="data-foot"><span>共 ${rows.length} 条记录</span><span>1 / 1 页</span></div>`}function searchable(placeholder='搜索名称、编号或状态'){return `<div class="toolbar"><input aria-label="搜索记录" placeholder="${placeholder}" oninput="filterTable(this.value)"><button onclick="filterTable('');$('.toolbar input').value=''">重置</button></div>`}function metricCards(items){return `<div class="metrics">${items.map(x=>`<div class="metric"><div class="metric-head"><span>${x[0]}</span><span class="badge gray">${x[3]||'演示'}</span></div><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div>`}
