function livePage(){return title('直播管理','直播、录播与伪直播统一排期，支持小程序和H5观看',`<button onclick="go('media')">扫码录制</button><button class="primary" onclick="newLive()">＋ 创建直播</button>`)+`<section class="card">${searchable('搜索直播名称、模式或状态')}${table(['直播名称','模式','计划时间','关联商品','自动回放','状态','操作'],db.rooms.map(r=>`<tr><td><b>${E(r.name)}</b><span class="secondary">房间ID：${r.id}</span></td><td>${E(r.mode)}</td><td>${E(r.time)}</td><td>${r.goods.length} 件</td><td>${r.record?'已开启':'未开启'}</td><td>${badge(r.status)}</td><td><div class="actions"><button class="link" onclick="openControl(${r.id})">中控台</button><button class="link" onclick="watch(${r.id})">观看页</button><button class="link" onclick="liveSettings(${r.id})">设置</button></div></td></tr>`))}</section>`}
function openControl(id){roomId=id;go('control')}function controlPage(){const r=room();return title('直播中控台',r.name,`<button onclick="go('live')">返回列表</button><button class="primary" onclick="toggleLive(${r.id})">${r.status==='直播中'?'结束并保存':r.status==='已结束'?'查看回放':'开始播放'}</button>`)+`<div class="live-control"><div><section class="card" style="padding:12px"><div class="control-video"><img src="assets/live-still.png" alt="用户提供的直播画面">${badge(r.status)}</div><div class="summary-row"><span>当前模式</span><b>${E(r.mode)}</b></div><div class="summary-row"><span>录像归档</span><b>${r.record?'自动录制已开启':'未开启'}</b></div><button class="link" onclick="watch(${r.id})">预览小程序直播间 →</button></section></div><div><section class="card"><div class="control-data">${[['在线人数','328'],['累计观看','1,286'],['支付金额','¥8,960'],['成交订单','56']].map(x=>`<div>${x[0]}<b>${x[1]}</b>示例统计</div>`).join('')}</div></section><section class="card"><div class="card-title"><h2>直播配置</h2><span class="source-pill">PPT 第4页</span></div><div class="control-tools">${[['comments','直播助手','自动评论 / 欢迎 / 关键词回复'],['warmup','直播暖场','时间轴与暖场脚本'],['sync','多平台同步','小程序 / H5 / 外部推流'],['liveGoods','商品配置','上架 / 讲解 / 橱窗排序'],['checkin','签到积分','用户签到与积分奖励'],['giftbag','抽奖福袋','抽奖参与与发放'],['data','直播访问数据','来源 / 留存 / 观看行为'],['heat','商品热度分析','曝光 / 点击 / 成交'],['profile','用户画像','新老客 / 地域 / 消费'],['replay','直播回放设置','自动录制 / 点播权限'],['topic','自定义专题','主题与分享封面'],['promotion','渠道推广','推广码 / 邀请榜 / 分享奖励']].map(x=>`<button onclick="controlAction('${x[0]}')">${x[1]}<small>${x[2]}</small></button>`).join('')}</div></section><section class="card"><div class="card-title"><h2>正在讲解的商品</h2><button class="link" onclick="controlAction('liveGoods')">管理橱窗</button></div>${r.goods.map(id=>{const p=product(id);return `<div class="row">${productPic(p,'thumb')}<div class="grow"><b>${E(p.name)}</b><p class="muted">${currency(p.price)} / 库存 ${p.stock}</p></div><button class="small ${r.explain===p.id?'primary':''}" onclick="explainProduct(${p.id})">${r.explain===p.id?'正在讲解':'开始讲解'}</button></div>`}).join('')}</section></div></div>`}
function mediaPage(){return title('录制与素材','采集APP扫码绑定电脑后台，录制结束自动保存并归档',`<button onclick="uploadMedia()">上传视频</button><button class="primary" onclick="pairDevice()">＋ 扫码连接APP</button>`)+`<div class="steps"><div class="step"><b>1. PC生成连接码</b>绑定门店、老师与录制任务</div><div class="step"><b>2. 采集APP扫码确认</b>开始录制，后台同步状态</div><div class="step"><b>3. 自动保存归档</b>上传 → 校验 → 转码 → 可用</div><div class="step"><b>4. 内容复用</b>录播点播 / 伪直播排期</div></div><section class="card"><div class="card-title"><h2>当前采集设备</h2>${badge(captureConnected?'已连接':'未连接')}</div><div class="row"><span class="quick-icon">${icon('phone')}</span><div class="grow"><b>${captureConnected?'老师的手机采集APP':'尚未连接手机'}</b><p class="muted" id="record-status">${recording?'录制中 / '+fmt(seconds):'本地录制与后台归档演示'}</p></div><button class="primary" onclick="${captureConnected?'toggleRecord()':'pairDevice()'}">${recording?'结束并自动保存':captureConnected?'开始录制':'生成连接码'}</button><button onclick="switchSurface('capture')">查看APP采集端</button></div></section><section class="card"><div class="card-title"><h2>素材库</h2><span class="muted">不可用素材不能发布</span></div>${searchable('搜索录像名称或来源')}${table(['素材名称','时长','来源','归档日期','状态','操作'],db.assets.map(a=>`<tr><td><b>${E(a.name)}</b></td><td>${E(a.duration)}</td><td>${E(a.source)}</td><td>${E(a.date)}</td><td>${badge(a.status)}</td><td><div class="actions"><button class="link" onclick="previewVideo(${a.id})">预览</button><button class="link" onclick="newLive(${a.id})" ${a.status!=='可用'?'disabled':''}>用于伪直播</button>${a.status==='待处理'?`<button class="link" onclick="processMedia(${a.id})">模拟转码完成</button>`:''}</div></td></tr>`))}</section>`}
function commentsPage(){return title('直播助手','自动评论、入场欢迎、关键词回复与评论管理',`<button class="primary" onclick="addScript()">＋ 添加自动评论</button>`)+`<div class="split"><section class="card"><h2>自动互动配置</h2><div class="field"><label for="script-room">应用场次</label><select id="script-room" onchange="db.commentRoom=Number(this.value);persist()">${db.rooms.map(r=>`<option value="${r.id}" ${db.commentRoom===r.id?'selected':''}>${E(r.name)}</option>`).join('')}</select></div><div class="field"><label class="check"><input type="checkbox" ${db.auto?'checked':''} onchange="setAutoComments(this.checked)">启用自动评论</label></div><div class="field"><label for="autoInterval">脚本轮播间隔（秒）</label><input id="autoInterval" type="number" min="2" max="120" value="${autoCommentInterval()}" onchange="saveAutoInterval(this.value)"><p class="form-help">首轮按时间轴发送，脚本完成后循环；自动消息始终标注运营助手身份。</p></div><div class="field"><label class="check"><input type="checkbox" ${db.configs.assistant?.welcome?'checked':''} onchange="saveAssistant('welcome',this.checked)">入场自动欢迎</label></div><div class="field"><label>关键词回复</label><input id="keyword" placeholder="如：优惠券" value="${E(db.configs.assistant?.keyword||'优惠券')}"></div><div class="field"><label>回复内容</label><textarea id="keywordReply">${E(db.configs.assistant?.reply||'新人优惠券可在领券中心领取，满199元可用。')}</textarea></div><button class="primary" onclick="saveKeywords()">保存回复规则</button><p class="form-help">自动消息以“运营助手 · 自动”身份展示，真人评论单独管理。</p></section><section class="card"><div class="card-title"><h2>时间轴评论脚本</h2><span class="badge gray">首轮按播放时间，完成后循环</span></div>${db.comments.map(c=>`<div class="row"><span class="badge">${fmt(c.at)}</span><div class="grow">${E(c.text)}<p class="form-help">${c.room?'房间 '+c.room:'全部场次'}</p></div><button class="link danger" onclick="deleteScript(${c.id})">删除</button></div>`).join('')}<button class="link" style="margin-top:15px" onclick="watch(db.commentRoom)">查看自动评论效果 →</button></section></div><section class="card"><div class="card-title"><h2>评论与用户管理</h2><button class="link" onclick="configure('moderation')">审核规则</button></div>${table(['用户名','评论内容','状态','操作'],[['小鹿','这款精华适合什么肤质？'],['顾客A','护理券周末可以用吗？']].map((x,i)=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${badge(db.configs['muted'+i]?'已禁言':'正常')}</td><td><button class="link" onclick="db.configs['muted${i}']=!db.configs['muted${i}'];persist();render();toast('评论权限已更新')">${db.configs['muted'+i]?'解除禁言':'禁言'}</button></td></tr>`))}</section>`}
function goodsPage(){return title('商品管理','实物商品、护理服务券与美业课程，统一库存与上架管理',`<button class="primary" onclick="editProduct()">＋ 发布商品</button>`)+`<section class="card">${searchable('搜索商品名称、分类或状态')}${table(['商品','销售价','库存','销量','商品类型','状态','操作'],db.products.map(p=>`<tr><td><div class="product-cell">${productPic(p,'thumb')}<div><b>${E(p.name)}</b><span class="secondary">${E(p.category)} / 商品ID ${p.id}</span></div></div></td><td>${currency(p.price)}</td><td>${p.stock}</td><td>${p.sold}</td><td>${E(p.type)}</td><td>${badge(p.active?'已上架':'已下架')}</td><td><div class="actions"><button class="link" onclick="editProduct(${p.id})">编辑</button><button class="link" onclick="toggleProduct(${p.id})">${p.active?'下架':'上架'}</button><button class="link" onclick="viewProduct(${p.id})">预览</button></div></td></tr>`))}</section>`}
function ordersPage(){const list=db.orders.filter(o=>orderFilter==='全部'||o.status===orderFilter);return title('订单管理','支付、发货、自提核销与售后退款',`<button onclick="batchWaybill()">批量打印面单</button><button onclick="configure('payment')">支付配置</button>`)+`<section class="card"><div class="tabs">${['全部','待支付','待发货','待核销','已发货','已完成','售后处理中','已退款'].map(t=>`<button class="${orderFilter===t?'active':''}" onclick="orderFilter='${t}';render()">${t}</button>`).join('')}</div>${searchable('搜索订单编号、顾客或状态')}${table(['订单信息','商品','金额 / 支付','配送方式','订单状态','操作'],list.map(o=>`<tr><td><b>${E(o.id)}</b><span class="secondary">${E(o.name)} / ${E(o.date)}</span></td><td>${E(product(o.product).name)} ×${o.qty}</td><td>${currency(o.total)}<span class="secondary">${E(o.payment)}</span></td><td>${E(o.delivery)}<span class="secondary">${E(o.store)}</span></td><td>${badge(o.status)}</td><td><div class="actions"><button class="link" onclick="orderDetail('${o.id}')">详情</button>${o.status==='待发货'?`<button class="link" onclick="shipOrder('${o.id}')">发货</button>`:''}${o.status==='待核销'?`<button class="link" onclick="redeem('${o.code}')">核销</button>`:''}${o.status==='售后处理中'?`<button class="link" onclick="reviewRefund('${o.id}')">审核退款</button>`:''}<button class="link" onclick="printReceipt('${o.id}')">小票</button></div></td></tr>`))}</section>`}
function membersPage(){return title('会员管理','会员等级、消费记录、积分、余额与用户画像')+metricCards([['会员总数','2,486','演示会员数据'],['我的积分',db.points,'签到和抽奖实时变化','本地'],['我的余额',currency(db.wallet),'充值和余额支付实时变化','本地'],['推广佣金',currency(db.commission),'可申请提现','本地']])+`<section class="card">${searchable('搜索会员名称或等级')}${table(['会员','等级','消费金额','积分','余额','操作'],[[db.userName,'体验会员','368'],['演示顾客A','银卡会员','1,268'],['演示顾客B','金卡会员','3,680']].map((u,i)=>`<tr><td>${E(u[0])}</td><td>${u[1]}</td><td>¥${u[2]}</td><td>${i===0?db.points:260+i*180}</td><td>${i===0?currency(db.wallet):'¥120.00'}</td><td><button class="link" onclick="memberProfile(${i})">会员详情</button></td></tr>`))}</section>`}
function marketingPage(){return title('营销中心','完整覆盖PPT第8—10页的8类营销能力',`<button onclick="switchSurface('mini')">顾客端体验</button>`)+`<div class="modules">${marketing.map(m=>`<article class="module"><div class="quick-icon">${icon(m.icon)}</div><h2>${m.name}<span class="source-pill">PPT P${m.slide}</span></h2><p>${m.desc}</p><div class="actions"><button class="primary small" onclick="configure('${m.id}')">配置活动</button><button class="small" onclick="miniFeature('${m.id}')">前台体验</button></div></article>`).join('')}</div><section class="card" style="margin-top:20px"><div class="card-title"><h2>已创建活动</h2><span class="muted">后台保存后在此查看</span></div>${table(['活动名称','活动类型','创建时间','状态','操作'],db.campaigns.map((c,i)=>`<tr><td>${E(c.name)}</td><td>${E(c.type)}</td><td>${today}</td><td>${badge(c.enabled?'启用':'暂停')}</td><td><button class="link" onclick="db.campaigns[${i}].enabled=!db.campaigns[${i}].enabled;persist();render()">${c.enabled?'暂停':'启用'}</button></td></tr>`))}</section>`}
function distributionPage(){return title('推广与分销','推广员、分享奖励、佣金与邀请榜',`<button onclick="configure('distribution')">佣金设置</button><button class="primary" onclick="promotionModal()">创建推广链接</button>`)+metricCards([['推广员','128','演示注册数据'],['累计邀请','1,286','按分享渠道归因'],['我的邀请人数',db.invited,'演示累计人数','本地'],['我的可提现佣金',currency(db.commission),'已结算佣金','本地']])+`<div class="split"><section class="card"><div class="card-title"><h2>直播邀请榜</h2><button class="link" onclick="miniFeature('rank')">顾客端邀请榜</button></div>${table(['排名','推广员','邀请人数','佣金'],[['1','顾客A','52','¥128.00'],['2','顾客B','43','¥108.50'],['3',db.userName,db.invited,currency(db.commission)]].map(x=>`<tr>${x.map(v=>`<td>${E(v)}</td>`).join('')}</tr>`))}</section><section class="card"><h2>渠道来源</h2>${[['公众号','486'],['视频号','328'],['好友分享','260'],['线下门店二维码','212']].map(x=>`<div class="summary-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}<button class="link" onclick="configure('channel')">渠道与分享奖励配置 →</button></section></div>`}
function storesPage(){return title('门店与核销','门店自提、服务履约与一次性核销',`<button onclick="configure('stores')">门店设置</button><button class="primary" onclick="redeem()">扫码 / 输入核销码</button>`)+`<section class="card"><div class="card-title"><h2>直营网点</h2><span class="badge ok">营业中</span></div><div class="row"><span class="quick-icon">${icon('pin')}</span><div class="grow"><h3>悦己美学 · 总部旗舰店</h3><p class="muted">${E(db.configs.stores?.['门店地址']||'演示地址：品牌体验中心一层')} / 10:00—21:00</p></div><button class="small" onclick="miniFeature('stores')">查看小程序门店</button></div></section><section class="card"><h2 style="margin-bottom:18px">待核销与核销记录</h2>${table(['核销码','订单','商品','状态','操作'],db.orders.filter(o=>['待核销','已核销'].includes(o.status)).map(o=>`<tr><td>${E(o.code)}</td><td>${E(o.id)}</td><td>${E(product(o.product).name)}</td><td>${badge(o.status)}</td><td>${o.status==='待核销'?`<button class="link" onclick="redeem('${o.code}')">核销</button>`:'已完成'}</td></tr>`))}</section>`}
function servicePage(){return title('在线客服','统一接待小程序与H5顾客咨询')+`<div class="split"><section class="card"><h2>当前会话</h2><div class="row"><span class="quick-icon">${icon('users')}</span><div><b>${E(db.userName)}</b><p class="muted">来自：直播间 / 未结束</p></div></div><div class="inset" style="height:310px;overflow:auto" id="staff-chats">${db.chats.map(c=>`<p style="padding:7px 0"><b>${c.from==='staff'?'客服':E(db.userName)}：</b>${E(c.text)}<small class="muted"> ${E(c.time)}</small></p>`).join('')}</div><div class="toolbar" style="margin:14px 0 0"><input id="staff-reply" placeholder="输入客服回复" aria-label="客服回复"><button class="primary" onclick="sendService('staff')">发送</button></div></section><section class="card"><h2>顾客与快捷回复</h2><div class="summary-row"><span>会员等级</span><b>体验会员</b></div><div class="summary-row"><span>最近订单</span><b>${db.orders.length} 单</b></div><div class="field"><label>快捷话术</label><select id="quickReply"><option>您好，请问有什么可以帮您？</option><option>到店前请与门店确认可预约时间。</option><option>请在我的订单提交售后，我们会及时处理。</option></select></div><button onclick="$('#staff-reply').value=$('#quickReply').value">填入回复</button><button class="link" style="display:block;margin-top:18px" onclick="miniFeature('service')">查看顾客端客服 →</button></section></div>`}
function messagesPage(){return title('消息中心','公众号模板、小程序提醒、短信与站内通知',`<button class="primary" onclick="newNotification()">＋ 创建通知</button>`)+`<section class="card">${table(['通知标题','渠道','目标用户','状态','操作'],db.notifications.map((n,i)=>`<tr><td>${E(n.title)}</td><td>${E(n.channel)}</td><td>${E(n.audience)}</td><td>${badge(n.state)}</td><td><button class="link" onclick="sendNotification(${i})">${n.state==='已发送'?'查看记录':'模拟发送'}</button></td></tr>`))}</section><section class="card"><h2>触发通知</h2><div class="support-grid" style="margin-top:18px">${['开播提醒','订单支付成功','订单已发货','退款状态','自提核销','积分到账'].map(x=>`<div class="support-item"><h3>${x}</h3><p>对应事件发生后生成通知任务</p><button class="link" onclick="configure('messages')">模板与渠道配置</button></div>`).join('')}</div></section>`}
function shopPage(){return title('商城装修','商品首页、会员中心、专题活动与资讯，支持专属商城和自有商城对接',`<button onclick="configure('mallConnect')">对接自有商城</button><button class="primary" onclick="switchSurface('mini')">预览小程序</button>`)+`<div class="shop-admin-preview"><div><section class="card"><h2>首页模块与视觉</h2><form onsubmit="saveShop(event)"><div class="field"><label for="shopName">商城名称</label><input id="shopName" required value="${E(db.settings['商城名称'])}"></div><div class="field"><label for="bannerTitle">首页活动标题</label><input id="bannerTitle" value="${E(db.settings.bannerTitle||'秋季美肤节')}"></div><div class="field"><label for="bannerSub">活动副标题</label><input id="bannerSub" value="${E(db.settings.bannerSub||'直播专享好物 · 新人福利')}"></div><div class="field"><label>首页风格</label><div class="template-options"><div class="template-option active">美业商城 · 粉色促销</div><div class="template-option">专属品牌主题</div></div></div><div class="inset">首页轮播 → 10项功能入口 → 商城头条 → 新人领券 → 直播入口 → 商品推荐 → 底部导航</div><button class="primary" style="margin-top:16px">保存装修</button></form></section><section class="card"><h2>内容与公告</h2><div class="row"><div class="grow"><b>商城头条</b><p class="muted">${E(db.configs.news?.['公告标题'])}</p></div><button class="small" onclick="configure('news')">编辑</button></div><div class="row"><div class="grow"><b>直播专题</b><p class="muted">主题标题、分享封面与课程分组</p></div><button class="small" onclick="configure('topic')">配置</button></div></section></div><section class="card"><h2>前台页面清单</h2>${['商城首页','商品分类','商品详情','直播广场','直播间','购物车与结算','订单与售后','会员中心','营销活动','客服与通知'].map(x=>`<div class="summary-row"><span>${x}</span>${badge('已覆盖')}</div>`).join('')}</section></div>`}
function financePage(){return title('收款与提现','支付渠道、商户收款资料、余额与佣金提现',`<button class="primary" onclick="configure('payment')">收款配置</button>`)+metricCards([['支付成功金额','¥23,168.00','示例统计'],['余额资产',currency(db.wallet),'原型本地账户','本地'],['已结算佣金',currency(db.commission),'原型可提现','本地'],['提现申请',String(db.withdrawals.length),'待审核 '+db.withdrawals.filter(w=>w.status==='待审核').length,'本地']])+`<section class="card"><div class="card-title"><h2>支付渠道</h2><button class="link" onclick="configure('merchant')">商户收款资料</button></div>${table(['渠道','适用场景','状态','操作'],[['余额支付','小程序 / H5'],['微信支付','小程序 / 公众号 / H5'],['支付宝支付','H5（依渠道支持）']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${badge(db.configs.payment?'配置已保存':'待接入')}</td><td><button class="link" onclick="configure('payment')">配置</button></td></tr>`))}</section><section class="card"><div class="card-title"><h2>提现申请</h2><button class="link" onclick="miniFeature('withdraw')">顾客端提现入口</button></div>${table(['申请编号','金额','收款方式','状态','操作'],db.withdrawals.map((w,i)=>`<tr><td>${E(w.id)}</td><td>${currency(w.amount)}</td><td>${E(w.method)}</td><td>${badge(w.status)}</td><td>${w.status==='待审核'?`<button class="link" onclick="reviewWithdrawal(${i})">审核</button>`:'—'}</td></tr>`))}</section>`}
function shippingPage(){return title('物流与打印','包邮规则、物流查询、电子面单与小票打印',`<button onclick="configure('shipping')">运费 / 包邮规则</button><button class="primary" onclick="batchWaybill()">批量面单</button>`)+`<div class="modules">${operations.filter(o=>['shipping','waybill','receipt','logistics'].includes(o.id)).map(o=>`<article class="module"><div class="quick-icon">${icon(o.icon)}</div><h2>${o.name}</h2><p>${o.desc}</p><button class="small" onclick="configure('${o.id}')">设置与演示</button></article>`).join('')}</div><section class="card" style="margin-top:18px"><h2 style="margin-bottom:18px">订单物流</h2>${table(['订单','快递公司','运单号','状态','操作'],db.orders.filter(o=>o.delivery==='快递配送').map(o=>`<tr><td>${E(o.id)}</td><td>${E(o.carrier||'待选择')}</td><td>${E(o.tracking||'暂无')}</td><td>${badge(o.status)}</td><td><button class="link" onclick="logistics('${o.id}')">轨迹</button> <button class="link" onclick="waybill('${o.id}')">面单</button></td></tr>`))}</section>`}
function dataPage(){return title('数据分析','直播访问数据、商品热度、用户画像与渠道转化')+metricCards([['直播访问','1,286','示例累计去重用户'],['商品点击','326','示例点击人数'],['直播成交','56','示例成交订单'],['支付转化率','4.35%','56 / 1,286']])+`<div class="chart-pair"><section class="card"><div class="card-title"><h2>观看与成交趋势</h2><span class="badge gray">示例数据</span></div>${chart()}</section><section class="card"><h2>用户画像</h2>${[['新用户','46%'],['老会员','54%'],['女性顾客','82%'],['主要年龄','25—40岁'],['主要来源','公众号 / 好友分享']].map(x=>`<div class="summary-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</section></div><section class="card"><h2 style="margin-bottom:16px">商品热度分析</h2>${table(['商品','曝光','点击','成交','转化率'],db.products.map((p,i)=>`<tr><td>${E(p.name)}</td><td>${986-i*130}</td><td>${126-i*21}</td><td>${26-i*5}</td><td>${((26-i*5)/(126-i*21)*100).toFixed(1)}%</td></tr>`))}</section>`}
function settingsPage(){return title('系统设置','账号权限、直播技术配置、集成接口与稳定性监控',`<button onclick="resetDemoDialog()">重置演示数据</button>`)+`<div class="support-grid">${[['roles','账号与权限','品牌管理员 / 运营 / 主播 / 门店核销员'],['stream','视频与推流','高清画质、推流参数、录制、回放与低延迟配置'],['sync','多端直播与同步','小程序、H5、公众号、外部平台同步配置'],['risk','直播与收款风控','内容审核、登录保护、支付异常、访问限制'],['performance','并发与稳定性','播放监控、任务重试、容量和告警'],['merchant','商户收款资料','商户主体、渠道、订单归属与收款资料'],['mallConnect','自有商城对接','商品、订单和会员接口映射'],['messages','消息集成','公众号、小程序、短信与站内消息'],['waybill','电子面单服务','快递100等面单服务接入'],['receipt','小票打印机','易联云等打印设备接入'],['logistics','物流服务','快递鸟 / 快递100查询配置'],['custom','定制与主题','自定义页面专题与业务字段']].map(x=>`<div class="support-item"><h3>${x[1]}</h3><p>${x[2]}</p><button class="small" onclick="configure('${x[0]}')">配置</button></div>`).join('')}</div><section class="card" style="margin-top:18px"><h2 style="margin-bottom:12px">操作日志</h2>${db.logs.slice(0,8).map(l=>`<div class="summary-row"><span>${E(l.text)}</span><span class="muted">${E(l.time)}</span></div>`).join('')||'<div class="empty">操作后将在此生成日志</div>'}</section>`}
function coveragePage(){return title('PPT功能核对','第8页20项功能全部对应，附前台、后台和集成位置')+`<div class="split"><section class="card"><div class="coverage-count">20 / 20</div><h2>核心功能已覆盖到原型</h2><p class="muted">8项营销 + 12项运营；外部服务为配置与模拟流程。</p></section><section class="card"><h2>额外范围</h2><div class="summary-row"><span>PPT第4页直播中控</span><b>12个操作入口</b></div><div class="summary-row"><span>用户额外要求</span><b>扫码录制 / 自动存储 / 自动评论</b></div><div class="summary-row"><span>三个播放模式</span><b>直播 / 录播 / 伪直播</b></div></section></div><section class="card">${table(['PPT页码','功能','原型行为','后台入口','顾客端'],coverage.map(m=>`<tr><td>P${m.slide}</td><td><b>${m.name}</b></td><td class="source-col">${m.desc}</td><td><button class="link" onclick="${marketing.some(k=>k.id===m.id)?`configure('${m.id}')`:operationAction(m.id)}">打开模块</button></td><td><button class="link" onclick="miniFeature('${m.id}')">体验</button></td></tr>`))}</section><div class="notice">PPT中的高并发、毫秒级、秒到账和防封宣传属于技术与服务承诺，需要真实环境验证。原型提供配置与业务流程，不表示这些性能已实现。</div>`}
function operationAction(id){return ({multichannel:"go('live')",refund:"go('orders')",withdraw:"go('finance')",service:"go('service')",messages:"go('messages')",stores:"go('stores')"}[id]||`configure('${id}')`)}

